if HandoffManager._visible:
	HandoffManager._on_ready_pressed()
return HandoffManager._visible

var lv = tree.root.get_node_or_null("Main/BoardRoot/LOSLineVisual")
if lv == null:
	return "no LOSLineVisual on BoardRoot"
if lv.current_line != null or lv.get_node("Line").visible:
	return "a line is drawn before any hover"
return "ok"

var main = tree.root.get_node("Main")
var units = GameState.state["units"]
units["U_KAPTIN_BADRUKK_A"]["models"][0]["position"] = {"x": 400.0, "y": 1200.0}
units["U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H"]["models"][0]["position"] = {"x": 1000.0, "y": 1200.0}
main._recreate_unit_visuals()
TerrainManager.load_terrain_from_save([{"id": "t11_decor", "type": "ruins", "position": [1500.0, 600.0], "size": [120.0, 120.0], "height_category": "tall", "rotation": 0.0, "traits": []}])
GameState.state["board"]["terrain_features"] = TerrainManager.terrain_features.duplicate(true)
var ids = PackedStringArray()
for f in TerrainManager.terrain_features:
	ids.append("%s:%s" % [str(f.id), TerrainManager.category_of(f)])
return ",".join(ids)

var sc = tree.root.get_node("Main/ShootingController")
var ph = PhaseManager.get_current_phase_instance()
return "%s|%s" % [sc.active_shooter_id, ph.active_shooter_id]

var b = GameState.create_snapshot(false)
var sl = RulesEngine.unit_sight_line("U_KAPTIN_BADRUKK_A", "U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H", b, false)
var cov = TerrainManager.unit_has_cover_11e(b["units"]["U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H"], b["units"]["U_KAPTIN_BADRUKK_A"]["models"][0])
var elig = tree.root.get_node("Main/ShootingController").eligible_targets.has("U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H")
return "sees=%s cover=%s eligible=%s" % [str(sl.has_los), str(cov), str(elig)]

var lv = tree.root.get_node("Main/BoardRoot/LOSLineVisual")
var sc = tree.root.get_node("Main/ShootingController")
if lv.current_line != null:
	return "current_line still set: %s" % str(lv.current_line)
if lv.get_node("Line").visible:
	return "Line2D still visible"
for c in sc.range_visual.get_children():
	if c.has_meta("is_range_label") and not c.is_queued_for_deletion():
		return "the range label stayed behind"
return "ok"

var lv = tree.root.get_node("Main/BoardRoot/LOSLineVisual")
var l = lv.current_line
if l == null:
	return "no line drawn"
if l.shooter_id != "U_KAPTIN_BADRUKK_A" or l.target_id != "U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H":
	return "wrong pair %s -> %s" % [l.shooter_id, l.target_id]
var sp = GameState.get_unit("U_KAPTIN_BADRUKK_A")["models"][0]["position"]
var tp = GameState.get_unit("U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H")["models"][0]["position"]
var s_w = Vector2(float(sp.x), float(sp.y))
var t_w = Vector2(float(tp.x), float(tp.y))
if l.from.distance_to(s_w) > 0.5 or l.to.distance_to(t_w) > 0.5:
	return "endpoints %s -> %s are not the base centres %s -> %s" % [str(l.from), str(l.to), str(s_w), str(t_w)]
var line = lv.get_node("Line")
if not line.visible or line.points.size() != 2 or line.points[0] != l.from or line.points[1] != l.to:
	return "Line2D does not run from -> to: visible=%s points=%s" % [str(line.visible), str(line.points)]
if not line.default_color.is_equal_approx(UIConstants.CONFIRMED_GREEN):
	return "Line2D painted %s, not CONFIRMED_GREEN" % line.default_color.to_html()
var xf = line.get_global_transform_with_canvas()
var screen_w = line.width * absf(xf.get_scale().x)
if absf(screen_w - 3.0) > 0.25:
	return "stroke is %.2f px on screen, not 3" % screen_w
var main = tree.root.get_node("Main")
var ends = {"U_KAPTIN_BADRUKK_A": xf * line.points[0], "U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H": xf * line.points[1]}
var seen = 0
for tok in main.get_node("BoardRoot/TokenLayer").get_children():
	if not tok.has_meta("unit_id") or not ends.has(str(tok.get_meta("unit_id"))):
		continue
	var c = main.world_to_screen_position(tok.position)
	var e = ends[str(tok.get_meta("unit_id"))]
	if c.distance_to(e) > 1.0:
		return "line end %s is %.1f px from its token centre %s" % [str(e), c.distance_to(e), str(c)]
	seen += 1
if seen != 2:
	return "found %d of the 2 tokens" % seen
if tree.root.get_node_or_null("Main/BoardRoot/ShootingLoSVisual") != null:
	return "the old red ShootingLoSVisual line still exists (two lines)"
return "ok"

var img = Image.load_from_file(ProjectSettings.globalize_path("user://test_results/scenarios/T11_los_line_T11_a_clear.png"))
if img == null:
	return "no capture"
var lv = tree.root.get_node("Main/BoardRoot/LOSLineVisual")
var line = lv.get_node("Line")
if lv.current_line == null or line.points.size() != 2:
	return "no line drawn"
var p = line.get_global_transform_with_canvas() * line.points[0].lerp(line.points[1], 0.25)
var px = img.get_pixel(int(round(p.x)), int(round(p.y)))
var best = ""
var bd = 99.0
for slot in ["CONFIRMED_GREEN", "MARGINAL_YELLOW", "INVALID_RED"]:
	var c = UIConstants.all_slots()[slot]
	var d = absf(c.r - px.r) + absf(c.g - px.g) + absf(c.b - px.b)
	if d < bd:
		bd = d
		best = slot
if bd > 0.2:
	return "pixel %s at %s is no slot colour (nearest %s, %.2f)" % [px.to_html(false), str(p), best, bd]
return best

